import { render } from '@solidjs/web';
import { Loading } from 'solid-js';

import fetchProfileData from './mock-api';
import ProfilePage from './profile';

const App = () => {
  const { user, posts, trivia } = fetchProfileData();
  return (
    <Loading fallback={<h1>Loading...</h1>}>
      <ProfilePage user={user()} posts={posts()} trivia={trivia()} />
    </Loading>
  );
};

render(App, document.getElementById('app'));

import { For, Loading, Reveal } from 'solid-js';

const ProfileDetails = (props) => <h1>{props.user?.name}</h1>;

const ProfileTimeline = (props) => (
  <ul>
    <For each={props.posts}>{(post) => <li>{post.text}</li>}</For>
  </ul>
);

const ProfileTrivia = (props) => (
  <>
    <h2>Fun Facts</h2>
    <ul>
      <For each={props.trivia}>{(fact) => <li>{fact.text}</li>}</For>
    </ul>
  </>
);

const ProfilePage = (props) => (
  <>
    <Loading fallback={<h1>Loading profile...</h1>}>
      <ProfileDetails user={props.user} />
    </Loading>
    <Loading fallback={<h2>Loading posts...</h2>}>
      <ProfileTimeline posts={props.posts} />
    </Loading>
    <Loading fallback={<h2>Loading fun facts...</h2>}>
      <ProfileTrivia trivia={props.trivia} />
    </Loading>
  </>
);

export default ProfilePage;

import { createMemo } from 'solid-js';

export default function fetchProfileData() {
  const user = createMemo(fetchUser);
  const posts = createMemo(fetchPosts);
  const trivia = createMemo(fetchTrivia);
  return { user, posts, trivia };
}

function fetchUser() {
  return new Promise((resolve) => {
    setTimeout(() => {
      resolve({
        name: 'Ringo Starr',
      });
    }, 500);
  });
}

let ringoPosts = [
  {
    id: 0,
    text: 'I get by with a little help from my friends',
  },
  {
    id: 1,
    text: "I'd like to be under the sea in an octupus's garden",
  },
  {
    id: 2,
    text: 'You got that sand all over your feet',
  },
];

function fetchPosts() {
  let ringoPostsAtTheTime = ringoPosts;

  return new Promise((resolve) => {
    setTimeout(() => {
      resolve(ringoPostsAtTheTime);
    }, 800);
  });
}

function fetchTrivia() {
  return new Promise((resolve) => {
    setTimeout(() => {
      resolve([
        {
          id: 1,
          text: 'The nickname "Ringo" came from his habit of wearing numerous rings.',
        },
        {
          id: 2,
          text: 'Plays the drums left-handed with a right-handed drum set.',
        },
        {
          id: 3,
          text: 'Nominated for one Daytime Emmy Award, but did not win',
        },
      ]);
    }, 200);
  });
}

